DROP PROCEDURE IF EXISTS usp_genalarmsplittable;

delimiter //
create procedure usp_genalarmsplittable(strOriTableName varchar(20), iAlarmGroupID int, iSplitTabNO int)
BEGIN
DECLARE tablename VARCHAR(40);
DECLARE indexname VARCHAR(40);
DECLARE pkname VARCHAR(40);
SET tablename = concat(strOriTableName, '_', iAlarmGroupID, '_', iSplitTabNO);
SET indexname = concat('ix', SUBSTRING(tablename,2), '_lstid');
SET pkname = concat('pk', SUBSTRING(tablename,2), '_id');

SET @sqltext = concat('DROP TABLE IF EXISTS ', tablename);
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET @sqltext = concat('CREATE TABLE ', tablename, '  ENGINE=MyISAM SELECT * FROM ', strOriTableName, ' WHERE 1 = 0');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET  @sqltext:=concat('ALTER TABLE ', tablename, ' ADD CONSTRAINT ', pkname, ' PRIMARY KEY (clogid)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (clstid)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_neid');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (cneid)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_recvoccurutctime');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (crecvoccurutctime)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_recvclearutctime');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (crecvclearutctime)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_confirmutctime');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (cconfirmutctime)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_confirmuser');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (cconfirmuser)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
SET indexname = concat('ix', SUBSTRING(tablename,2), '_custominfo');
SET  @sqltext:=concat('CREATE INDEX ', indexname, ' ON ', tablename, ' (ccustominfo)');
     PREPARE sqlstr from @sqltext;
     Execute sqlstr;
END
//

